def _internal_test_script() -> str:
    return """import { existsSync, readFileSync } from "node:fs";

const requiredFiles = [
  "src/App.tsx",
  "src/data/worlds.ts",
  "src/engine/safety.ts",
  "src/engine/storage.ts",
  "docs/interaction-design.md",
  "docs/internal-playtest-plan.md"
];

for (const file of requiredFiles) {
  if (!existsSync(file)) throw new Error(`Missing required file: ${file}`);
}

const app = readFileSync("src/App.tsx", "utf8");
const worlds = readFileSync("src/data/worlds.ts", "utf8");
const styles = readFileSync("src/styles.css", "utf8");
const storage = readFileSync("src/engine/storage.ts", "utf8");
const packageJson = JSON.parse(readFileSync("package.json", "utf8"));

const checks = [
  ["formal package", packageJson.name === "huohutu-spark-official-game"],
  ["adventure map", app.includes("adventureMap") && app.includes("levelSelect")],
  ["moment-to-moment fun loop", app.includes("funLoop") && app.includes("comboMeter")],
  ["reward and retry feedback", app.includes("rewardBurst") && app.includes("blockedReason")],
  ["vibecoding studio", app.includes("vibeCodingStudio") && app.includes("AI导演")],
  ["simulated AI director creates playable cards", app.includes("directorQueue") && app.includes("灵感卡")],
  ["two worlds with quest depth", worlds.includes("rainbow-island") && worlds.includes("story-planet") && worlds.match(/quest-/g)?.length >= 6],
  ["tablet app shell", styles.includes(".tabletShell") && styles.includes(".stageArena")],
  ["parent value", app.includes("家长火花册") && app.includes("成长回放")],
  ["test lab", app.includes("内测实验室") && packageJson.scripts["test:fun"] === "node scripts/fun-playtest.mjs"],
  ["fresh formal storage", storage.includes("huohutu.spark.official.formal.v1")],
];

const failed = checks.filter(([, ok]) => !ok).map(([name]) => name);
if (failed.length) throw new Error(`Formal internal checks failed: ${failed.join(", ")}`);

console.log(JSON.stringify({ ok: true, checks: checks.map(([name]) => name) }, null, 2));
"""


def _user_sim_script() -> str:
    return """import { readFileSync } from "node:fs";

const app = readFileSync("src/App.tsx", "utf8");
const worlds = readFileSync("src/data/worlds.ts", "utf8");
const styles = readFileSync("src/styles.css", "utf8");

const checks = [
  ["child enters a real game surface", app.includes("开始今天的冒险") && app.includes("adventureMap")],
  ["can play without typing", app.includes("playAction(action)") && app.includes("actionCard")],
  ["player agency beyond one prompt", app.includes("levelSelect") && app.includes("activeQuest")],
  ["world visibly changes", app.includes("stageObject") && app.includes("unlockedObjects")],
  ["reward loop", app.includes("rewardBurst") && app.includes("星星奖励")],
  ["fail/retry loop", app.includes("blockedReason") && app.includes("还缺少")],
  ["vibecoding turns ideas into playable changes", app.includes("runDirectorIdea") && app.includes("directorQueue")],
  ["parent can understand value", app.includes("成长回放") && app.includes("Spark 能力线索")],
  ["tablet-first UI", styles.includes("min-height: calc(100vh - 82px)") && styles.includes(".actionGrid")],
  ["formal game is not MVP copy", !app.includes("可玩 MVP") && !app.includes("游戏化内测版")],
  ["campaign depth", worlds.match(/action-/g)?.length >= 16],
];

const failed = checks.filter(([, ok]) => !ok).map(([name]) => name);
if (failed.length) throw new Error(`Formal user simulation failed: ${failed.join(", ")}`);

console.log(JSON.stringify({
  ok: true,
  simulatedPersonas: ["child-player", "parent-reviewer", "vibecoding-creator", "internal-game-tester"],
  checks: checks.map(([name]) => name)
}, null, 2));
"""


