def _safety_ts() -> str:
    return """export function sanitizeIdea(text: string): { safeText: string; redirected: boolean } {
  const unsafe = ["炸", "杀", "死", "打人", "毁掉", "血"];
  if (unsafe.some((word) => text.includes(word))) {
    return { safeText: "把危险想法改造成守护任务，让伙伴更安全", redirected: true };
  }
  return { safeText: text, redirected: false };
}
"""


def _spark_ts() -> str:
    return """import type { GameEvent, SparkKey, SparkScores } from "../types";

export const sparkLabels: Record<SparkKey, string> = {
  expression: "表达",
  creativity: "创造",
  story: "故事",
  science: "科学",
  social: "社交",
  nature: "自然",
  aiCollaboration: "AI协作"
};

export function summarizeSpark(events: GameEvent[], scores: SparkScores): string {
  const strongest = Object.entries(scores).sort((a, b) => b[1] - a[1])[0]?.[0] ?? "expression";
  return `最近 ${events.length} 个片段里，孩子最明显的火花是 ${sparkLabels[strongest as SparkKey]}。`;
}
"""


def _storage_ts() -> str:
    return """import { initialProgress } from "../data/worlds";
import type { GameState, SparkScores } from "../types";

const storageKey = "huohutu.spark.official.formal.v1";

export const zeroSpark: SparkScores = {
  expression: 0,
  creativity: 0,
  story: 0,
  science: 0,
  social: 0,
  nature: 0,
  aiCollaboration: 0
};

export function createGame(): GameState {
  return {
    activeWorldId: "rainbow-island",
    ageBand: "5-6",
    progress: initialProgress(),
    sparkScores: { ...zeroSpark },
    events: [],
    directorQueue: [],
    soundOn: true
  };
}

export function loadGame(): GameState {
  const raw = window.localStorage.getItem(storageKey);
  if (!raw) return createGame();
  try {
    const parsed = JSON.parse(raw) as GameState;
    if (!parsed.progress?.["rainbow-island"] || !parsed.progress?.["story-planet"]) return createGame();
    return parsed;
  } catch {
    return createGame();
  }
}

export function saveGame(state: GameState): void {
  window.localStorage.setItem(storageKey, JSON.stringify(state));
}

export function resetGame(): GameState {
  const next = createGame();
  saveGame(next);
  return next;
}
"""


def _app_tsx() -> str:
    return """import { useEffect, useMemo, useState } from "react";
import { worlds } from "./data/worlds";
import { sanitizeIdea } from "./engine/safety";
import { loadGame, resetGame, saveGame } from "./engine/storage";
import type { GameAction, GameEvent, GameState, Mode, SparkKey, WorldId } from "./types";
import "./styles.css";

const sparkLabels: Record<SparkKey, string> = {
  expression: "表达",
  creativity: "创造",
  story: "故事",
  science: "科学",
  social: "社交",
  nature: "自然",
  aiCollaboration: "AI协作"
};

const ideaChips = ["给小兔做云朵滑梯", "把星星路灯变成音乐", "让彩虹桥会唱歌"];

function unique(values: string[]): string[] {
  return [...new Set(values)];
}

function applySpark(state: GameState, keys: SparkKey[]): GameState["sparkScores"] {
  const next = { ...state.sparkScores };
  for (const key of keys) next[key] = Math.min(100, next[key] + 8);
  return next;
}

export default function App() {
  const [game, setGame] = useState<GameState>(() => loadGame());
  const [mode, setMode] = useState<Mode>("play");
  const [idea, setIdea] = useState("");
  const [rewardBurst, setRewardBurst] = useState("开始今天的冒险");

  useEffect(() => saveGame(game), [game]);

  const activeWorld = worlds[game.activeWorldId];
  const progress = game.progress[game.activeWorldId];
  const activeQuest = activeWorld.quests.find((quest) => quest.id === progress.activeQuestId) ?? activeWorld.quests[0];
  const activeQuestActions = activeQuest.actionIds.map((id) => activeWorld.actions.find((action) => action.id === id)).filter(Boolean) as GameAction[];
  const latestActiveEvent = game.events.find((event) => event.worldId === activeWorld.id);
  const questDoneCount = activeQuest.actionIds.filter((id) => progress.completedActionIds.includes(id)).length;
  const questPercent = Math.round((questDoneCount / activeQuest.actionIds.length) * 100);
  const totalStars = Object.values(game.progress).reduce((sum, item) => sum + item.stars, 0);
  const totalXp = Object.values(game.progress).reduce((sum, item) => sum + item.xp, 0);

  const funPlaytestChecks = [
    { label: "孩子不用打字也能玩", ok: game.events.some((event) => event.actionId.startsWith("action-")) },
    { label: "至少一次合成/建造", ok: game.events.some((event) => event.objects.length > 0) },
    { label: "出现星星奖励", ok: totalStars > 0 },
    { label: "两个世界都有进度", ok: new Set(game.events.map((event) => event.worldId)).size >= 2 },
    { label: "vibecoding 生成可玩变化", ok: game.directorQueue.length > 0 }
  ];

  function update(mutator: (current: GameState) => GameState) {
    setGame((current) => mutator(current));
  }

  function selectWorld(worldId: WorldId) {
    update((current) => ({ ...current, activeWorldId: worldId }));
  }

  function selectQuest(questId: string) {
    update((current) => {
      const currentProgress = current.progress[current.activeWorldId];
      return {
        ...current,
        progress: {
          ...current.progress,
          [current.activeWorldId]: { ...currentProgress, activeQuestId: questId }
        }
      };
    });
  }

  function playAction(action: GameAction) {
    update((current) => {
      const world = worlds[current.activeWorldId];
      const worldProgress = current.progress[world.id];
      const missing = action.requires.filter((token) => !worldProgress.inventory.includes(token));
      const blockedReason = missing.length ? `还缺少：${missing.join("、")}。先去收集或完成前置挑战。` : undefined;
      const completedActionIds = blockedReason ? worldProgress.completedActionIds : unique([...worldProgress.completedActionIds, action.id]);
      const inventory = blockedReason ? worldProgress.inventory : unique([...worldProgress.inventory, ...action.grants]);
      const unlockedObjects = blockedReason ? worldProgress.unlockedObjects : unique([...worldProgress.unlockedObjects, action.object]);
      const active = world.quests.find((quest) => quest.id === worldProgress.activeQuestId) ?? world.quests[0];
      const completedQuestIds = active.actionIds.every((id) => completedActionIds.includes(id))
        ? unique([...worldProgress.completedQuestIds, active.id])
        : worldProgress.completedQuestIds;
      const stars = completedQuestIds.includes(active.id) && !worldProgress.completedQuestIds.includes(active.id)
        ? worldProgress.stars + 1
        : worldProgress.stars;
      const event: GameEvent = {
        id: `event-${Date.now()}-${action.id}`,
        at: new Date().toISOString(),
        worldId: world.id,
        questId: active.id,
        actionId: action.id,
        childInput: action.prompt,
        result: blockedReason ?? action.result,
        spark: action.spark,
        grants: blockedReason ? [] : action.grants,
        objects: blockedReason ? [] : [action.object],
        blockedReason
      };
      setRewardBurst(blockedReason ? "再试一次" : `星星奖励 +${stars > worldProgress.stars ? 1 : 0} · ${action.fun}`);
      return {
        ...current,
        progress: {
          ...current.progress,
          [world.id]: {
            ...worldProgress,
            inventory,
            unlockedObjects,
            completedActionIds,
            completedQuestIds,
            stars,
            xp: blockedReason ? worldProgress.xp : worldProgress.xp + action.xp,
            combo: blockedReason ? 0 : worldProgress.combo + 1
          }
        },
        sparkScores: blockedReason ? current.sparkScores : applySpark(current, action.spark),
        events: [event, ...current.events].slice(0, 120)
      };
    });
  }

  function runDirectorIdea(text = idea) {
    const cleaned = sanitizeIdea(text.trim());
    if (!cleaned.safeText) return;
    update((current) => {
      const worldProgress = current.progress[current.activeWorldId];
      const token = `灵感卡-${current.directorQueue.length + 1}`;
      const object = `${cleaned.safeText.slice(0, 8)}造物`;
      const card = {
        id: `director-${Date.now()}`,
        idea: text,
        playableChange: `${cleaned.safeText}，已经变成下一轮可玩的舞台机关。`,
        grantedToken: token
      };
      const event: GameEvent = {
        id: `event-${Date.now()}-director`,
        at: new Date().toISOString(),
        worldId: current.activeWorldId,
        questId: worldProgress.activeQuestId,
        actionId: "director-card",
        childInput: cleaned.safeText,
        result: cleaned.redirected ? `安全改写：${card.playableChange}` : card.playableChange,
        spark: ["expression", "creativity", "aiCollaboration"],
        grants: [token],
        objects: [object]
      };
      setRewardBurst("AI导演生成了新机关");
      return {
        ...current,
        directorQueue: [card, ...current.directorQueue].slice(0, 8),
        progress: {
          ...current.progress,
          [current.activeWorldId]: {
            ...worldProgress,
            inventory: unique([...worldProgress.inventory, token]),
            unlockedObjects: unique([...worldProgress.unlockedObjects, object]),
            xp: worldProgress.xp + 12,
            combo: worldProgress.combo + 1
          }
        },
        sparkScores: applySpark(current, ["expression", "creativity", "aiCollaboration"]),
        events: [event, ...current.events].slice(0, 120)
      };
    });
    setIdea("");
  }

  const topSpark = useMemo(() => {
    return Object.entries(game.sparkScores).sort((a, b) => b[1] - a[1])[0] as [SparkKey, number];
  }, [game.sparkScores]);

  return (
    <main className="tabletShell">
      <header className="topBar">
        <div><strong>火火兔 Spark 正式游戏</strong><span>vibecoding 参考：说出想法，马上变成可玩的世界变化</span></div>
        <nav><button className={mode === "play" ? "on" : ""} onClick={() => setMode("play")}>进入游戏</button><button className={mode === "parent" ? "on" : ""} onClick={() => setMode("parent")}>家长火花册</button><button className={mode === "lab" ? "on" : ""} onClick={() => setMode("lab")}>内测实验室</button></nav>
      </header>

      {mode === "play" ? (
        <section className="gameScreen">
          <aside className="adventureMap">
            <h2>冒险地图</h2>
            {Object.values(worlds).map((world) => <button key={world.id} className={game.activeWorldId === world.id ? "selected" : ""} onClick={() => selectWorld(world.id)}><strong>{world.name}</strong><span>{world.tagline}</span></button>)}
            <h2>levelSelect</h2>
            {activeWorld.quests.map((quest) => <button key={quest.id} className={progress.activeQuestId === quest.id ? "selected" : ""} onClick={() => selectQuest(quest.id)}><strong>{quest.title}</strong><span>完成条件：{quest.finish}</span></button>)}
            <button className="reset" onClick={() => { setGame(resetGame()); setRewardBurst("重新开始今天的冒险"); }}>重置体验</button>
          </aside>

          <section className="funLoop">
            <div className="goalCard">
              <div><span>今天目标</span><h1>{activeQuest.goal}</h1><p>{activeWorld.companion}陪你玩 · 当前世界：{activeWorld.name}</p></div>
              <div className="comboMeter"><strong>{questPercent}%</strong><i><b style={{ width: `${questPercent}%` }} /></i><span>连击 {progress.combo} · 星星 {progress.stars} · XP {progress.xp}</span></div>
            </div>

            <section className="stageArena" style={{ "--sky": activeWorld.palette.sky, "--ground": activeWorld.palette.ground, "--accent": activeWorld.palette.accent } as React.CSSProperties}>
              <div className="sun" /><div className="ground" /><div className="portal" />
              {progress.unlockedObjects.map((object, index) => <button className={`stageObject o${(index % 8) + 1}`} key={`${object}-${index}`} onClick={() => playAction(activeQuestActions[Math.min(index, activeQuestActions.length - 1)] ?? activeWorld.actions[0])}>{object}</button>)}
              <article className="companion"><strong>{activeWorld.companion}</strong><span>{latestActiveEvent?.result ?? "点一张行动卡开始玩，世界会马上变化。"}</span></article>
              <div className="rewardBurst">{rewardBurst}</div>
            </section>

            <section className="inventory"><div><strong>背包</strong><span>{progress.inventory.length ? progress.inventory.join(" · ") : "先去收集材料"}</span></div><div><strong>成长</strong><span>总星星 {totalStars} · 总 XP {totalXp}</span></div></section>

            <section className="actionGrid">
              {activeQuestActions.map((action) => {
                const missing = action.requires.filter((token) => !progress.inventory.includes(token));
                const done = progress.completedActionIds.includes(action.id);
                const blockedReason = missing.length ? `还缺少 ${missing.join("、")}` : "";
                return <button className={`actionCard ${done ? "done" : ""}`} key={action.id} onClick={() => playAction(action)}><small>{action.fun}</small><strong>{action.title}</strong><span>{blockedReason || "可行动"}</span></button>;
              })}
            </section>

            <form className="vibeCodingStudio" onSubmit={(event) => { event.preventDefault(); runDirectorIdea(); }}>
              <div><strong>AI导演 vibecoding 工坊</strong><span>孩子说一个想法，系统生成可玩机关，不只是显示文字。</span></div>
              <div className="ideaChips">{ideaChips.map((chip) => <button type="button" key={chip} onClick={() => runDirectorIdea(chip)}>{chip}</button>)}</div>
              <label><input value={idea} onChange={(event) => setIdea(event.target.value)} placeholder="例如：让彩虹桥会唱歌" /><button type="submit">生成可玩变化</button></label>
            </form>
          </section>
        </section>
      ) : mode === "parent" ? (
        <section className="parentBook">
          <header><div><span>成长回放</span><h1>Spark 能力线索</h1></div><button onClick={() => update((current) => ({ ...current, soundOn: !current.soundOn }))}>{game.soundOn ? "声音开" : "声音关"}</button></header>
          <article className="summary"><h2>{sparkLabels[topSpark[0]]}最亮</h2><p>孩子已经完成 {game.events.length} 个游戏片段，获得 {totalStars} 颗星星。家长可以从片段里看到表达、共情、创造和 AI 协作线索。</p></article>
          <section className="sparkGrid">{Object.entries(game.sparkScores).map(([key, value]) => <div key={key}><span>{sparkLabels[key as SparkKey]}</span><meter min="0" max="100" value={value} /><strong>{value}</strong></div>)}</section>
          <section className="timeline">{game.events.slice(0, 10).map((event) => <article key={event.id}><strong>{worlds[event.worldId].name} · {event.childInput}</strong><p>{event.result}</p><small>{event.spark.map((key) => sparkLabels[key]).join(" · ")}</small></article>)}</section>
        </section>
      ) : (
        <section className="lab">
          <header><div><span>正式游戏门禁</span><h1>内测实验室</h1></div><button onClick={() => setGame(resetGame())}>清空重测</button></header>
          <section className="checks">{funPlaytestChecks.map((check) => <p className={check.ok ? "ok" : ""} key={check.label}>{check.ok ? "通过" : "待测"} · {check.label}</p>)}</section>
          <section className="timeline">{game.directorQueue.map((card) => <article key={card.id}><strong>灵感卡 · {card.grantedToken}</strong><p>{card.playableChange}</p></article>)}</section>
        </section>
      )}
    </main>
  );
}
"""


def _styles_css() -> str:
    return """:root { font-family: Inter, "PingFang SC", "Microsoft YaHei", system-ui, sans-serif; color: #18314a; background: #eef5fb; } * { box-sizing: border-box; } body { margin: 0; min-width: 320px; min-height: 100vh; } button, input { font: inherit; } button { cursor: pointer; }
.tabletShell { min-height: 100vh; display: grid; grid-template-rows: auto 1fr; }
.topBar { min-height: 82px; display: flex; align-items: center; justify-content: space-between; gap: 18px; padding: 16px 24px; background: #fff; border-bottom: 1px solid #d8e7f4; position: sticky; top: 0; z-index: 10; } .topBar strong, .topBar span { display: block; } .topBar strong { font-size: 21px; } .topBar span { color: #60758a; } .topBar nav { display: flex; gap: 8px; background: #edf5fb; padding: 5px; border-radius: 8px; } .topBar nav button { border: 0; border-radius: 7px; padding: 10px 14px; color: #52677c; background: transparent; font-weight: 900; } .topBar nav .on { background: #18314a; color: #fff; }
.gameScreen { display: grid; grid-template-columns: 310px minmax(0, 1fr); min-height: calc(100vh - 82px); }
.adventureMap { display: grid; align-content: start; gap: 12px; padding: 18px; background: #fff; border-right: 1px solid #d8e7f4; } .adventureMap h2 { margin: 12px 0 0; font-size: 14px; color: #698199; } .adventureMap button { border: 1px solid #d7e6f2; border-radius: 8px; background: #fff; padding: 12px; text-align: left; color: #18314a; } .adventureMap button strong, .adventureMap button span { display: block; } .adventureMap button span { color: #60758a; line-height: 1.4; margin-top: 4px; } .adventureMap .selected { border-color: #34bea8; background: #e9fbf6; } .adventureMap .reset { margin-top: 14px; text-align: center; background: #f5f8fc; }
.funLoop { padding: 20px; display: grid; gap: 15px; align-content: start; }
.goalCard, .inventory, .actionGrid, .vibeCodingStudio, .parentBook header, .summary, .sparkGrid, .timeline, .lab header, .checks { border: 1px solid #d7e6f2; border-radius: 8px; background: #fff; padding: 15px; }
.goalCard { display: flex; justify-content: space-between; gap: 16px; align-items: center; } .goalCard span, .goalCard p { color: #60758a; margin: 0; } .goalCard h1 { margin: 4px 0 6px; font-size: 25px; line-height: 1.16; } .comboMeter { min-width: 230px; display: grid; gap: 7px; } .comboMeter strong { font-size: 30px; } .comboMeter i { height: 14px; border-radius: 999px; background: #e4eef7; overflow: hidden; } .comboMeter b { display: block; height: 100%; background: linear-gradient(90deg, #34bea8, #ff8c6a); }
.stageArena { --sky: #8bd8ff; --ground: #8bdc91; --accent: #ff8c6a; min-height: 470px; position: relative; overflow: hidden; border: 1px solid rgba(24,49,74,.12); border-radius: 8px; background: linear-gradient(180deg, var(--sky) 0%, #f7fbff 62%, var(--ground) 63%, var(--ground) 100%); box-shadow: inset 0 -50px 100px rgba(24,49,74,.1); }
.sun, .ground, .portal, .stageObject, .companion, .rewardBurst { position: absolute; } .sun { right: 8%; top: 10%; width: 90px; height: 90px; border-radius: 50%; background: #ffd166; box-shadow: 0 0 0 18px rgba(255,209,102,.25); } .ground { left: -5%; right: -5%; bottom: -72px; height: 172px; border-radius: 55% 55% 0 0; background: rgba(255,255,255,.28); } .portal { left: 12%; top: 14%; width: 175px; height: 88px; border-radius: 999px; border: 14px solid rgba(255,255,255,.7); }
.stageObject { min-width: 94px; max-width: 150px; min-height: 54px; border: 2px solid rgba(24,49,74,.12); border-radius: 8px; background: rgba(255,255,255,.94); color: #18314a; font-weight: 900; box-shadow: 0 14px 30px rgba(24,49,74,.16); animation: bob 2.6s ease-in-out infinite; } .o1 { left: 10%; bottom: 82px; } .o2 { left: 29%; bottom: 138px; } .o3 { left: 50%; bottom: 96px; } .o4 { right: 13%; bottom: 154px; } .o5 { right: 8%; bottom: 74px; } .o6 { left: 17%; top: 114px; } .o7 { right: 30%; top: 96px; } .o8 { left: 43%; top: 172px; }
@keyframes bob { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-8px); } }
.companion { left: 24px; bottom: 24px; width: min(390px, calc(100% - 48px)); background: #18314a; color: #fff; border-radius: 8px; padding: 15px; box-shadow: 0 18px 36px rgba(24,49,74,.24); } .companion span { display: block; color: #d8eeff; line-height: 1.45; margin-top: 5px; } .rewardBurst { right: 22px; top: 22px; background: #fff7e6; color: #8a4a14; border: 1px solid #ffd28b; border-radius: 8px; padding: 12px 14px; font-weight: 900; }
.inventory { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; } .inventory strong, .inventory span { display: block; } .inventory span { color: #60758a; margin-top: 4px; }
.actionGrid { display: grid; grid-template-columns: repeat(4, minmax(150px, 1fr)); gap: 12px; } .actionCard { min-height: 126px; border: 1px solid #d7e6f2; border-radius: 8px; background: #fbfdff; color: #18314a; padding: 12px; display: grid; gap: 7px; text-align: left; align-content: start; } .actionCard small { color: #ff8c6a; font-weight: 900; } .actionCard strong { font-size: 17px; } .actionCard span { color: #60758a; } .actionCard.done { background: #ecfbf6; border-color: #34bea8; }
.vibeCodingStudio { display: grid; gap: 12px; background: #fffaf0; border-color: #ffdb9f; } .vibeCodingStudio strong, .vibeCodingStudio span { display: block; } .vibeCodingStudio span { color: #6a7890; margin-top: 3px; } .ideaChips { display: flex; flex-wrap: wrap; gap: 8px; } .ideaChips button, .vibeCodingStudio label button, .parentBook header button, .lab header button { border: 0; border-radius: 8px; background: #ff8c6a; color: #fff; padding: 11px 14px; font-weight: 900; } .vibeCodingStudio label { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 10px; } .vibeCodingStudio input { border: 1px solid #cbd9e7; border-radius: 8px; min-height: 46px; padding: 0 13px; }
.parentBook, .lab { padding: 22px; display: grid; gap: 15px; } .parentBook header, .lab header { display: flex; justify-content: space-between; align-items: center; gap: 16px; } .parentBook h1, .lab h1 { margin: 4px 0 0; font-size: 30px; } .parentBook span, .lab span { color: #60758a; }
.summary { background: #fff7e6; border-color: #ffd28b; } .sparkGrid { display: grid; gap: 10px; } .sparkGrid div { display: grid; grid-template-columns: 110px minmax(120px, 1fr) 48px; gap: 10px; align-items: center; } meter { width: 100%; height: 16px; }
.timeline { display: grid; gap: 10px; } .timeline article { border: 1px solid #e2edf6; border-radius: 8px; padding: 12px; background: #fbfdff; } .timeline p { margin: 8px 0; color: #3d5268; } .timeline small { color: #60758a; }
.checks { display: grid; gap: 8px; } .checks p { margin: 0; border: 1px solid #e1edf6; border-radius: 8px; padding: 10px; } .checks .ok { background: #ecfbf6; border-color: #34bea8; }
@media (max-width: 980px) { .gameScreen { grid-template-columns: 1fr; } .adventureMap { border-right: 0; border-bottom: 1px solid #d8e7f4; } .actionGrid { grid-template-columns: repeat(2, minmax(150px, 1fr)); } .topBar { align-items: stretch; flex-direction: column; } }
@media (max-width: 620px) { .funLoop, .parentBook, .lab, .adventureMap { padding: 14px; } .goalCard, .parentBook header, .lab header { align-items: stretch; flex-direction: column; } .inventory, .actionGrid, .vibeCodingStudio label, .sparkGrid div { grid-template-columns: 1fr; } .stageArena { min-height: 520px; } }
"""


def _readme_md() -> str:
    return """# 火火兔 Spark 正式游戏交付线

这个版本把当前任务从“可玩 MVP”升级为正式游戏方向：以好玩、可持续试玩、AI 导演共创和儿童成长记录为核心。

## 核心参考：vibecoding

- 用户用自然语言描述想法。
- AI 导演把想法变成可玩的机关、道具或关卡变化。
- 玩家马上试玩，用手感、反馈、奖励和复玩意愿判断好坏。
- KUN 持续根据试玩结果迭代，不把“代码生成完成”误当“游戏完成”。

## 运行

```bash
npm install
npm run dev -- --host 127.0.0.1 --port 5178
```

## 验收

```bash
npm run build
npm run test:internal
npm run test:user-sim
npm run test:fun
```
"""
